INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-acrylic-putty', 'Dulux Acrylic Putty', 'Putty', 'putty', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/15/38/5d/b8/packshot_large.jpg', 'Dulux Acrylic Wall putty is formulated for filling cracks, joints, leveling uneven and rough masonry and plasterwork up to 3-4mm. It is also used for filling defective cement surfaces to give a smooth and excellent finish.', '["Easy to spread","Superior Whiteness","Excellent filling property"]'::jsonb, '1.85 sqm/Kg', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-damp-protect-2in1', 'Dulux Aquatech Damp Protect 2in1', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/d3/eb/2f/2e/160_x_160.png', 'Dulux Aquatech Exterior Damp Protect 2 in 1 is a high quality premium waterproofing coating that provides good water resistance when applied on both Exterior vertical walls & Roof surfaces. It''s revolutionary Damp Resist Technology bridges cracks and covers the porous wall or Roof surface with a thick film that creates a durable and protective layer. This helps in preventing water seepage thus providing better waterproofing on the applied surfaces.', '["8 years Waterproofing Performance","Crack bridging up to 1mm","Surface Temperature reduction of upto 10 deg C (On Roof)","Multi-surface Adhesion"]'::jsonb, 'upto 45 sqft/L for Vertical Surfaces; 9-11 sqft/L for Horizontal Surfaces', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-exterior-damp-protect-basecoat', 'Dulux Aquatech Exterior Damp Protect Basecoat', 'Exterior', 'exterior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/b8/2a/61/53/damp_protect_160_x_160.png', 'Dulux Aquatech DampProtect Basecoat is an Exterior Waterproof Basecoat that can be applied on vertical as well as horizontal surfaces. Its unique AquaProtect Technology prevents the penetration of water and can handle up to 5 bar of Hydrostatic Pressure, providing waterproofing performance for up to 5 years. The basecoat is efficient in bridging the cracks of up to 1mm and provides SunReflect property that helps to reduce the surface temperature by upto 5 Degree Celsius.', '["Crack bridging up to 1mm","Good adhesion","Strong reinforcing polyfibre network","5 Years Waterproofing performance"]'::jsonb, 'upto 45 sqft/L for Vertical Surfaces; 10-15 sqft/L for Horizontal Surfaces', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-exterior-pre-treatment-coat', 'Dulux Aquatech Exterior Pre Treatment Coat', 'Exterior', 'exterior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/cb/f4/58/19/packshot_large.png', '', '["Surface Prep Wash","FungiClean Technology","Anti algal & anti fungal"]'::jsonb, '112 sqm/L', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-exterior-pu-coat', 'Dulux Aquatech Exterior PU Coat', 'Exterior', 'exterior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/0e/97/6d/82/packshot_large.png', 'Dulux Aquatech Exterior PU coat is a superior waterproofing technology with hybrid Acrylic-Polyurethane technology and is suitable for both horizontal and vertical wall application. Its thick, elastomeric super protective film covers cracks of upto 4mm and the strong network of reinforced polymers makes the coating extremely tough and dirt & water resistant.', '["Superior Waterproofing Performance of upto 15 years","Upto 4mm crackbridging","Surface Temperature reduction of upto 12 deg C","Multi-surface Adhesion"]'::jsonb, '– upto 10 sqft/L for Horizontal Surfaces in 3 coats
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-flexible-waterproof-basecoat-advance', 'Dulux Aquatech Flexible Waterproof Basecoat Advance', 'Waterproofing', 'waterproofing', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/26/b0/d4/49/ext_advance_160_x_160.png', 'Dulux Aquatech Flexible Waterproof basecoat advance is a breakthrough in waterproofing technology. Its PU based polymer matrix forms a thick, elastic, super protective film, which covers the cracks and blocks water. And the strong network of polymer fibers makes the coating tough enough for waterproofing of side walls.', '["Strong reinforcing polyfibre network","Reduces exterior surface temperature up to 5 degrees"]'::jsonb, '30-45 Sq.ft/L', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-flexible-waterproof-basecoat-neo', 'Dulux Aquatech Flexible Waterproof Basecoat Neo', 'Waterproofing', 'waterproofing', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/c4/b5/45/1d/neo_160_x_160.png', 'Dulux Aquatech Flexible Waterproof basecoat Neo is a breakthrough in waterproofing technology. Its special tough polymer matrix forms a thick, elastic, super protective film, which covers the cracks and blocks water. And the strong network of polymer fibers makes the coating tough enough for waterproofing of side walls.', '["Strong reinforcing polyfibre network","Crack Bridging upto 2.5 mm","Good Alkaline Resistance","10 year Waterproofing Performance"]'::jsonb, '30-45 Sq.ft/L', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-interior-exterior-crackfiller-5mm-10mm-20mm', 'Dulux Aquatech Interior & Exterior Crackfiller (5mm/10mm/20mm)', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/ed/22/c8/ae/packshot_large.png', '', '["Fills cracks of upto 20mm","Shrinkfree- fills in just one application","Quick dry & tough- Accepts nails and screws in 4-6 hrs"]'::jsonb, '30-75 rft per Kg. (depending on Crack Filler Type)', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-interior-waterproof-basecoat', 'Dulux Aquatech Interior Waterproof Basecoat', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/f8/a8/af/19/packshot_large.png', 'Dulux Aquatech Interior Waterproof basecoat is an easy to apply, primer-upgrade waterproofing undercoat that is made up of micronized pigments and fillers forming an extremely tough film that protects the top coat layer from mild dampness. It offers 10X better water resistance and 2X higher stretchability against ordinary primers, thus providing better finish and performance to topcoats.', '["10X Better Waterproofing than Primer","2X Higher Stretchability than Primer","Improves Topcoat Finish & Performance"]'::jsonb, '180-200sqft/L/coat', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-interior-waterproof-basecoat-advance', 'Dulux Aquatech Interior Waterproof Basecoat Advance', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/23/dd/ac/7c/int_advance_160_x_160.png', 'Dulux Aquatech Interior Waterproof Basecoat Advance is an easy to apply, 1K film-forming waterproofing basecoat for interior surfaces which provides a long term solution against interior waterproofing problems like dampness and alkali attack, thus keeping the integrity of your paint film intact for longer period and enhancing the life of your walls', '["Crackproof technology","Ease of application"]'::jsonb, '50-60 Sq.ft/L', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-repair-pro-latex', 'Dulux Aquatech Repair Pro Latex', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/9d/24/f2/64/rpl_160_x_160.png', 'Dulux Aquatech Repair Pro Latex is a superior performing modified SBR (Styrene Butadiene Rubber) based repair polymer. It is used for the repair of old concrete, columns, beams, chajjas, waterproofing of toilets, balconies and sinking areas. It reduces shrinkage of concrete & thereby does not let crack form in the concrete even after multiple years. It contains plasticizers that improves the workability of the cement mix at low water ratios, providing better cohesion & bonding.', '["High water resistance"]'::jsonb, 'Not Applicable', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-roof-waterproof', 'Dulux Aquatech Roof Waterproof', 'Waterproofing', 'waterproofing', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/48/96/b2/1b/roof_160_x_160.png', 'Aquatech Roof Waterproof is a best in class product which provides protection on roofs and terraces for up to 12 years. Its unique PU Hybrid Technology forms a tougher, more elastic protective film of up to 600-800 microns over porous roof surfaces. The film is highly flexible which bridges cracks of up to 2mm preventing water seepage, carbonation and fungal attacks. The coating has got best in class adhesion and thus can be used on multiple surfaces like brickbat coba, plaster, china chips and mosaic tiles. In order to keep the surface cool during summers the coating also provides Sun Reflect of up to 10 degree Celsius.', '["Crack bridging up to 2mm","Suitable for waterproofing of sunken areas","Upto 10 deg C  Temperature Reduction with Sun Reflect","12 Years Waterproofing performance"]'::jsonb, '8-10 sqft/L', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-waterblock-2k', 'Dulux Aquatech Waterblock 2K', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/bd/c1/76/5e/packshot_large.png', 'Aquatech Waterblock 2k is a specialist 2 component product that provides protection against water penetration for interior walls, bathrooms and kitchens. Its unique Hydro breathe technology prevents swelling, blistering and chalking of paint. The breathable coating prevents the top paint layer from peeling off. The coating is suitable to be applied on the interior surface of swimming pools before applying tiling or topcoat. The product can be applied in water tanks as well.', '["2K Cementitious Waterproofing coating","Excellent anti-alkali property","Suitable for waterproofing of sunken areas","Superior anti-carbonation property"]'::jsonb, '10-15 sqft/kg/2 coats', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-waterproof-putty', 'Dulux Aquatech Waterproof Putty', 'Waterproofing', 'waterproofing', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/77/8e/83/96/packshot_large.jpg', 'Dulux Aquatech Waterproof Putty is a premium quality powder putty that is specially designed with silicone and anti-efflorescence additives to give unique waterproofing properties and efflorescence resistance for a smooth finish and extended life to the top coats.', '["Efflorescence resistance","High water resistance","High adhesive strength"]'::jsonb, '0.4 sqm/Kg', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-aquatech-waterproof-repair-polymer', 'Dulux Aquatech Waterproof Repair Polymer', 'Waterproofing', 'waterproofing', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/61/84/38/97/packshot_large.png', 'Dulux Aquatech Waterproof Repair Polymer (WRP) is a ready to use multipurpose latex-based bonding additive for use in mortars, bond coats, and waterproofing primers. It is used for repairing damaged concrete, columns, beams, and chajjas. It is also used for waterproofing of toilets, balconies, and sunken areas.', '["High adhesive strength","High water resistance","Improves hardness & abrasion resistance","High compressive strength"]'::jsonb, 'Not Applicable', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-polyputty', 'Dulux Polyputty', 'Putty', 'putty', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/36/41/3d/80/packshot_large.png', '', '["Polymer Based"]'::jsonb, '0.27 - 1.85 sqm/Kg', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-promise-exterior-primer', 'Dulux Promise Exterior Primer', 'Exterior', 'exterior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/fa/fd/66/f1/packshot_large.png', 'Dulux Promise Exterior Primer is a good quality, water-based primer for external surfaces. Its unique Anti-Peel formulation ensures superior adhesion for the paint film, thereby resisting peeling or flaking of the topcoat.', '["Better Coverage","Anti-Chalking","Fast Drying","Anti-Peel"]'::jsonb, '9.2-12 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-promise-interior-primer', 'Dulux Promise Interior Primer', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/8e/5f/70/64/packshot_large.png', 'Dulux Promise Interior Primer is a good quality primer having good adhesion to interior masonry surfaces, both new and previously decorated such as brickwork, plaster, cement, fibre boards, etc. It is specially formulated to give good filling property. Correct application of primer assures better quality and durability of the finished coat.', '["Superior Adhesion","Superior Whiteness","Anti-Chalking"]'::jsonb, '18.5 - 23.2 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-promise-sheen-exterior', 'Dulux Promise Sheen Exterior', 'Exterior', 'exterior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/d9/a1/47/b4/dulux_promise_sheen_ext_160x160.png', 'Dulux Promise Sheen Exterior Emulsion is a high quality, water based smooth emulsion paint which provides high sheen to your walls. Its Chroma Brite Glow-UV Fight Technology keeps the exterior wall colour brighter for longer. It is equipped with good coverage and good opacity formulation which gives a good finish to the walls and its unique Anti Peeling properties ensures that the paint film remains intact under the exterior weather conditions.', '["Best-in-Class Sheen","Advance Anti peel formula","ChromaBrite Technology"]'::jsonb, '4.6 - 5.6 sqm/L', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-promise-sheen-interior', 'Dulux Promise Sheen Interior', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/f7/d3/28/53/dulux_promise_sheen_int_160x160.png', 'Dulux Promise Sheen Interior Emulsion is a high quality, water based acrylic emulsion paint which provides high sheen to your walls. Its Chroma Brite Glow Technology keeps the interior wall colour brighter for longer. It is  equipped with good coverage and good opacity formula which gives a rich finish to walls  and its unique Anti Chalking properties prevents the paint film from chalking giving a fresh & bright look to your walls.', '["Rich and Soothing Sheen Finish","Advance Anti Chalking Formula","ChromaBrite Technology"]'::jsonb, '7.4 - 9.3 sqm/L', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-promise-smartchoice-exterior', 'Dulux Promise SmartChoice Exterior', 'Exterior', 'exterior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/ff/d5/d3/19/dulux_promise_sc_ext_160x160.png', 'Dulux Promise SmartChoice Exterior Emulsion is a good quality, water based emulsion paint. Equipped with good coverage and good opacity formulation, it covers a larger area in same quantity of paint and its Anti-Peeling properties ensures that the paint film remains intact giving smooth finish to your walls.', '["Good coverage & Opacity","Anti-Peel","Smooth Matt Finish"]'::jsonb, '5.6 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-promise-smartchoice-exterior-primer', 'Dulux Promise SmartChoice Exterior Primer', 'Exterior', 'exterior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/e0/9e/74/03/promise_sc_ext_primer_2025_copy_160x160.png', 'Dulux Promise Smartchoice Exterior Primer is a value for money, water-based primer for external surfaces. Its  formulation ensures superior adhesion for the paint film, thereby resisting peeling or flaking of the topcoat.', '["Superior Whiteness","Anti-Chalking"]'::jsonb, '19 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-promise-smartchoice-interior', 'Dulux Promise SmartChoice Interior', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/15/50/74/af/dulux_promise_int_sc_160x160.png', 'Dulux Promise SmartChoice Interior Emulsion is a good quality, water based emulsion paint. Equipped with good coverage and good opacity formulation, it covers a larger area in same quantity of paint and its Anti-Chalking properties prevents the paint film from chalking giving smooth finish to your walls.', '["Good coverage & Opacity","Anti-Chalking","Smooth Matt Finish"]'::jsonb, '9 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-promise-smartchoice-interior-primer', 'Dulux Promise SmartChoice Interior Primer', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/86/1d/da/fe/promise_sc_int_primer_2025_copy_160x160.png', 'Dulux Promise Smartchoice Interior Primer is a value for primer having good adhesion to interior masonry surfaces, both new and previously decorated such as brickwork, plaster, cement, fibre boards, etc. Correct application of primer assures better quality and durability of the finished coat.', '["Anti-Chalking","Fast Drying"]'::jsonb, '10 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-quick-drying-primer', 'Dulux Quick Drying Primer', 'Primer', 'primer', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/9d/48/7e/46/packshot_large.png', 'Dulux Quick Drying Primer is a premium quality water-based primer for application on wood and metal surfaces. It is ec0-friendly water-based undercoat with low odour and low voc. Unlike conventional solvent based primers it dries quickly and therefore the topcoat ca n be applied on the same day.', '["Water-based Primer for Wood & Metal","Superior Corrosion Resistance","Quick drying"]'::jsonb, '10.21 - 11.14 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-red-oxide-metal-primer', 'Dulux Red-oxide Metal Primer', 'Primer', 'primer', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/16/4a/45/e4/packshot_large.png', 'This is a solvent based economical primer anti-corrosive protective primer for interior and exterior ferrous and non-ferrous metal work, including steel work, new, weathered and pre-treated zinc and galvanized iron. It may also be applied over pre-treated aluminium.', '["Stronger Adhesion","Effective Corrosion Protection"]'::jsonb, '8.8 - 9.2 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-solvent-based-cement-primer', 'Dulux Solvent-based Cement Primer', 'Primer', 'primer', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/ad/94/29/10/packshot_large.png', '', '["Superior Adhesion","Better Top Coat Coverage","Better Quality Finish","Better Top Coat Durability"]'::jsonb, '9.2-11.1 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-superclean', 'Dulux SuperClean', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/2a/f3/ab/f8/super_160x160px01.png', 'Dulux SuperClean is an interior water-based, high-quality, durable, smooth emulsion paint developed using the unique High Bind Technology for decoration and protection purposes. Due to this special high bind technology, the latex particles bind together to form a compact film, which makes it harder for the stains to penetrate into the wall & thus enables easy cleaning of walls. With its Anti-Bacterial Property, it inhibits the growth of certain bacteria on the wall. Now, with new Silver Ion Technology, it comes with an added benefit of Anti-Viral property that helps to effectively work against certain Viruses. Dulux SuperClean gives a soothing sheen and a smooth finish to the walls, also its high washability gives an easy to maintain and clean walls which have a fresh look for many years to come.', '["High Washability","Super Smooth & Sheen Finish","Anti-Viral","Anti-Bacterial","Fungus Guard"]'::jsonb, '120-140 sq.ft/litre', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-superclean-3in1', 'Dulux SuperClean 3in1', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/78/d7/58/54/superclean_3in1_packshot_copy.jpg', 'Dulux SuperClean 3in1 mark resistance is an interior water-based high quality durable smooth emulsion paint developed using the unique scuff resistance, tough stain repellent & anti-bacterial technology for decoration and protection purpose. Dulux SuperClean 3in1 mark resistance gives soothing sheen and a rich finish to the walls for a beautiful & gorgeous look, also its high Washability gives an easy to maintain and clean walls which have a fresh look for many years to come. The tough film, resists marks & scuff, ensuring easy maintenance and long-lasting freshness.', '["Scuff Mark Resistance","Superior Washability","Rich and Soothing Sheen Finish","Tough Stain Repellent","Anti-Bacterial","Fungus Guard"]'::jsonb, '120-140 sq.ft/litre', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-supercover-ultra', 'Dulux SuperCover Ultra', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/22/32/45/9c/supercover_ultra_160x160.png', 'Dulux SuperCover Ultra is a smooth premium interior emulsion for walls and ceilling that enables you to bring home the long-lasting colors. Its Silicon technology and Color guard technology ensure that these colors are protected from daily wear and tear and last longer while providing high whiteness and hiding.', '["Silicone technology","Colourguard Technology - Long Lasting Colours","Anti-Bacterial","Fungal Guard","Smooth Matt Finish","High coverage","High opacity"]'::jsonb, '120-140 sqft/litre/2 coats', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-velvet-touch-eterna', 'Dulux Velvet Touch Eterna', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/be/21/08/fa/vt_eterna_tc160x160.png', '', '["Tru Colour+ with anti oxidants for long lasting richness and vibrancy of colours","PU Re Acrylic Dust Resistant technology for durable and dust free walls","Ultra smooth finish","High Washability","Refreshing aroma with added tea tree oil","10 years Warranty under Dulux Assurance*"]'::jsonb, '140-160 sq.ft', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-water-based-cement-primer', 'Dulux Water-based Cement Primer', 'Primer', 'primer', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/aa/55/97/de/packshot_large.png', 'Dulux Water Based Cement Primer is a water based primer, suitable for use on plastered masonry, POP, puttied, limed or pre-painted wall surfaces.', '["Superior Adhesion","Alkali Resistance","Superior Whiteness","Better Top Coat Coverage"]'::jsonb, '18.5 - 23.2 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-weathershield-alkali-bloc-pu-primer', 'Dulux Weathershield Alkali Bloc PU+ Primer', 'Primer', 'primer', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/af/49/64/76/pu_plus_160x160.png', 'Dulux Weathershield Alkali Bloc PU+ Exterior Primer is a superior quality, high-performance priming cum sealing system suitable for applications on external plaster surface to improve adhesion between wall and topcoat material. Enriched with Polyurethane technology, the primer penetrates the substrate effectively, sealing its pores. This results in a smooth, even topcoat with an impeccable finish.This primer is specially designed to give up to 10X water resistance against ordinary primers and excellent Alkali resistance to exterior masonry substrate, thus resists peeling or flaking of topcoat and enhances its life.', '["PU Reinforced Technology","Advanced Alkali Protection","Superior Adhesion","Anti - Chalking"]'::jsonb, '110-150 sqft/litre', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-weathershield-powerflexx', 'Dulux Weathershield Powerflexx', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/49/0b/2b/33/160.png', 'Dulux Weathershield Powerflexx is a high-performance ultra-premium exterior emulsion powered by Triple Defense Technology which provides superior protections against Cracks and Extreme Weather Conditions like heat, dust, and rain which damages the beauty of your house. With the backbone of  PU-MA (Polyurethane Modified Acrylic) & Silicon additives the paint film keeps your house protected and beautiful for upto 12 Years.', '["Superior Crack Proof","Triple Defence Technology","PU Modified Acrylic","Superior Weather Resistant"]'::jsonb, '4.6-6.0 sqm/L', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-weathershield-prime-coat', 'Dulux Weathershield Prime Coat', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/67/76/46/a6/prime_coat_160x160.png', '', '["Superior Adhesion","Superior Whiteness","Superior Coverage","Anti Alkali – Anti Efflorescence"]'::jsonb, '110 - 150 sqft./litre', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-weathershield-protect-dustproof', 'Dulux Weathershield Protect Dustproof', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/4d/03/05/f0/dust_proof_160x160.png', 'Dulux Weathershield Protect Dustproof (upgrade of Dulux Weathershield Protect) is a premium exterior acrylic emulsion specially designed for protection against the extreme weather elements like dust and sunlight. It has been enriched with Dust Shield Technology which resists dust from settling onto the exterior walls. Super durable binders that provide extreme protection against efflorescence & Anti fade colours that remain on the walls for longer periods of time.', '["6 Years Warranty","Dust shield Technology","Advanced Algal and Fungus Guard","SunReflect Technology"]'::jsonb, '50-60 Sqft./litre', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-weathershield-protect-rainproof', 'Dulux Weathershield Protect Rainproof', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/c5/53/25/b3/160.png', 'Dulux Weathershield Protect Rainproof is a premium exterior emulsion specially designed for protection against the extreme weather elements like rainfall, dust and sunlight. It has been enriched with super durable binders that provide extreme protection against efflorescene & algal attacks in the high humid & rainfall regions when compared normal exterior paints.', '["Silicone technology","High durability","Soft Sheen finish","Advanced Rainshield Technology"]'::jsonb, '4.6-6.0 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('dulux-zinc-yellow-metal-primer', 'Dulux Zinc Yellow Metal Primer', 'Primer', 'primer', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/76/19/02/9c/packshot_large.png', 'Dulux Zinc Yellow Metal Primer is a solvent based protective primer suitable for interior and exterior ferrous and surface treated non-ferrous metal work. It gives effective protection against Corrosion to the surface and has strong adhesion properties. Appropriate application of the primer ensures better protection to the metal surface as well as higher durability of finish coat.', '["Zinc-Phosphate Based","Stronger Adhesion","Superior Corrosion Resistance"]'::jsonb, '8.3 - 10.2 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
