INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('sadolin-opaque-2k-pu-primer-surfacer', 'Sadolin Opaque 2K PU Primer Surfacer', 'Primer', 'primer', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/9e/57/06/35/packshot_large.png', 'Sadolin PU is a high perfromance 2 componenet polyurethane wood finish offering upto 5X more protection, due to its ''Dual-Shield Technology''. It offers Stain, Scratch & Water Resistance to the Wooden Surfaces.', '["Excellent scratch & stain resistance","Wood crack protection","All Weather Durable & UV resistant"]'::jsonb, '80-90sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('velvet-touch-diamond-glo', 'Velvet Touch Diamond Glo', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/af/ed/63/a9/packshot_large.png', 'Dulux Velvet Touch Diamond Glo is a super premium quality, highly durable and washable emulsion paint with a best in class high sheen luxury finish. It is the only super premium interior emulsion that brings alive the smooth touch of Velvet and glo of Diamonds on the walls. Uniquely formulated with Surface slip technology, Diamond Glo has the Best in Class Stain and Water Repellence- better than any other ordinary emulsion. Now with Tru Color (Dura Color Technology), Velvet Touch is made with the finest ingredients and color pigments to deliver intense rich colors and ultra-smooth finish on your walls.', '["High sheen finish","Enhanced Smoothness","Best in class stain and water repellence","Surface Slip Technology","High durability"]'::jsonb, '10.21 - 13.93 sqm/L', true, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('velvet-touch-pearl-glo', 'Velvet Touch Pearl Glo', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/d0/3a/1c/5d/packshot_large.png', 'Dulux Velvet Touch Pearl Glo is a premium quality, highly durable and washable emulsion paint with a best mid sheen luxury finish. It is the only super premium interior emulsion that brings alive the smooth touch of velvet and soft glo of pearls on the walls. Now with Tru Color (Dura Color Technology), Velvet Touch is made with the finest ingredients and color pigments to deliver intense rich colors and ultra-smooth finish on your walls.', '["Mid sheen finish","Best-in-Class Smoothness","Long lasting pearl like finish","Protection from Finger Marking"]'::jsonb, '11.14 - 14.86 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
INSERT INTO products (id, name, category, category_id, image, description, features, coverage, popular, sizes, is_active) VALUES ('velvet-touch-platinum-glo', 'Velvet Touch Platinum Glo', 'Interior', 'interior', 'https://msp.images.akzonobel.com/prd/dh/aindlx/packshots/f1/e6/1b/97/packshot_large.png', 'Dulux Velvet Touch Platinum Glo is an uber premium paint with subtle platinum like glow. Moreover its superior dust & dirt resistance coupled with Class A washability makes your walls timelessly beautiful. Now with Tru Color (Dura Color Technology), Velvet Touch is made with the finest ingredients and color pigments to deliver intense rich colors and ultra-smooth finish on your walls.', '["Rich Matt finish","High durability","Best in class washability","Dirt and Dust Resistance"]'::jsonb, '12.07 - 13.93 sqm/L', false, '[{"size":"1L","mrp":0,"discountedPrice":0}]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, category_id = EXCLUDED.category_id, image = EXCLUDED.image, description = EXCLUDED.description, features = EXCLUDED.features, coverage = EXCLUDED.coverage, popular = EXCLUDED.popular, sizes = EXCLUDED.sizes;
